/// <summary>
/// PaffH 22.11.21
/// base class for DirPartyTable.BaseType dependend subclasses
/// is needed for setting the aliasname in the DirPartyTable
/// </summary>
abstract public class NDXDirPartyTableBaseType 
    implements NDXDirPartyTableBaseTypeI
{
    private static Map dictDirPartyInfo;
    private str fillChar;
    private str removeChar;

    DirPartyTable dirPartyTable;
    LogisticsPostalAddress primaryPostalAddress;



}

Method.Source:
/// <summary>
/// initialize dictDirPartyInfo
/// PaffH 23.11.21
/// </summary>
static void TypeNew()
{
    dictDirPartyInfo = new Map(Types::String, Types::Class);
}

/// <summary>
/// PaffH 24.11.21
/// </summary>
protected void new()
{
    fillChar = '_';
    removeChar = ' .';
}

/// <summary>
/// PaffH 24.11.21
/// fill _text with fillChar if _text.length() less _strLength
/// </summary>
/// <param name = "_text">str</param>
/// <param name = "_strLength">int</param>
/// <returns>str</returns>
public str fillWithChar(str _text, int _strLength)
{
    str newText = strRem(_text, removeChar);
    int missingChars = _strLength - strLen(newText);
    if (missingChars > 0)
    {
        newText = newText + strRep(fillChar, missingChars);
    }
    return subStr(newText, 1, _strLength);
}

/// <summary>
/// find or insert NDXDirPartyInfo
/// PaffH 23.11.21
/// </summary>
/// <param name = "_dirPartyNumber">DirPartyNumber</param>
/// <param name = "_nDXDirPartyInfo">optional NDXDirPartyInfo to insert</param>
/// <returns>NDXDirPartyInfo</returns>
public static NDXDirPartyInfo findDirPartyInfo(DirPartyNumber _dirPartyNumber, NDXDirPartyInfo _nDXDirPartyInfo = NDXDirPartyInfo::construct())
{
    NDXDirPartyInfo nDXDirPartyInfo;

    if (dictDirPartyInfo.exists(_dirPartyNumber))
    {
        nDXDirPartyInfo = dictDirPartyInfo.lookup(_dirPartyNumber);
    }
    else if (!prmIsDefault(_nDXDirPartyInfo))
    {
        dictDirPartyInfo.insert(_dirPartyNumber, _nDXDirPartyInfo);
        return _nDXDirPartyInfo;
    }
    else
    {
        nDXDirPartyInfo = NDXDirPartyInfo::construct();
    }
    return nDXDirPartyInfo;
}

/// <summary>
/// delete entry in dictionary dictDirPartyInfo
/// PaffH 23.11.21
/// </summary>
/// <param name = "_dirPartyNumber">DirPartyNumber to delete</param>
/// <returns>delete successful</returns>
public static boolean deleteDirPartyInfo(DirPartyNumber _dirPartyNumber)
{
    if (dictDirPartyInfo.exists(_dirPartyNumber))
    {
        dictDirPartyInfo.remove(_dirPartyNumber);
        return true;
    }
    return false;
}

/// <summary>
/// PaffH 22.11.21
/// build instance of baseclass NDXDirPartyTableBaseType 
/// depending on attribute (dirPartyBaseType)
/// </summary>
/// <param name = "_dirPartyTable">DirPartyTable</param>
/// <returns>instance of type NDXDirPartyTableBaseTypeI</returns>
public static NDXDirPartyTableBaseTypeI CreateInstance(DirPartyTable _dirPartyTable)
{
    NDXDirPartyTableBaseTypeAttribute attr = new NDXDirPartyTableBaseTypeAttribute(_dirPartyTable.baseType());
    NDXDirPartyTableBaseTypeI instance = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(NDXDirPartyTableBaseTypeI), attr);
    if (!instance || !(instance is NDXDirPartyTableBaseTypeI))
    {
        //SysExtensionCache::clearAllScopes();
        instance = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(NDXDirPartyTableBaseTypeI), attr);
        if (!instance || !(instance is NDXDirPartyTableBaseTypeI))
        {
            throw Error(Error::wrongUseOfFunction(funcName()));
        }
    }

    instance.parmDirPartyTable(_dirPartyTable);
    return instance;
}

/// <summary>
/// PaffH 27.02.23
/// </summary>
/// <param name = "_dirPartyTable">DirPartyTable</param>
/// <param name = "_LogisticsPostalAddress">LogisticsPostalAddress</param>
/// <returns>NDXDirPartyTableBaseTypeI</returns>
public static NDXDirPartyTableBaseTypeI CreateInstanceLogisticsPostalAddress(DirPartyTable _dirPartyTable, LogisticsPostalAddress _LogisticsPostalAddress)
{
    NDXDirPartyTableBaseTypeI instance = NDXDirPartyTableBaseType::CreateInstance(_dirPartyTable);
    instance.parmLogisticsPostalAddress(_LogisticsPostalAddress);
    return instance;
}

/// <summary>
/// PaffH 22.11.21
/// </summary>
/// <param name = "_dirPartyTable">DirPartyTable</param>
/// <returns>get/set DirPartyTable</returns>
public DirPartyTable parmDirPartyTable(DirPartyTable _dirPartyTable = dirPartyTable)
{
    dirPartyTable = _dirPartyTable;
    return dirPartyTable;
}

/// <summary>
/// PaffH 27.02.23
/// </summary>
/// <param name = "_logisticsPostalAddress">primaryPostalAddress</param>
/// <returns>LogisticsPostalAddress</returns>
public LogisticsPostalAddress parmLogisticsPostalAddress(LogisticsPostalAddress _logisticsPostalAddress = primaryPostalAddress)
{
    primaryPostalAddress = _logisticsPostalAddress;
    return primaryPostalAddress;
}

/// <summary>
/// PaffH 21.02.23
/// build NameAlias from Name- and City-Part
/// </summary>
/// <param name = "_namePart">str</param>
/// <param name = "_namePartLength">int</param>
/// <param name = "_cityPart">str</param>
/// <param name = "_cityPartLength">int</param>
/// <returns>new NameAlias</returns>
public str buildNameAlias(str _namePart, int _namePartLength, str _cityPart, int _cityPartLength)
{
    return this.fillWithChar(_namePart, _namePartLength) + this.fillWithChar(_cityPart, _cityPartLength);
}

/// <summary>
/// PaffH 23.02.23
/// build new NameAlias from 2 NameParts
/// </summary>
/// <param name = "_namePart1">NamePart 1</param>
/// <param name = "_namePart2">NamePart 2</param>
/// <returns>new NameAlias</returns>
abstract public str buildNameAliasFromNameParts(str _namePart1, str _namePart2)
{
}

/// <summary>
/// PaffH 23.02.23
/// get Name1, Name2, Name3 as one string (from primary address)
/// </summary>
/// <returns>"Name1 Name2 Name3"</returns>
public str primaryPostalAddressName123()
{
    LogisticsPostalAddress postalAddress = this.primaryPostalAddress();
    return strLTrim(strRTrim(strFmt('%1 %2 %3', postalAddress.NDXLogisticsLocationName1,
        postalAddress.NDXLogisticsLocationName2,
        postalAddress.NDXLogisticsLocationName3)));
}

/// <summary>
/// PaffH 23.02.23
/// get primary Postal Address
/// </summary>
/// <returns>LogisticsPostalAddress</returns>
public LogisticsPostalAddress primaryPostalAddress()
{
    return primaryPostalAddress ? primaryPostalAddress : DirParty::primaryPostalAddress(dirPartyTable.RecId);
}
